def minimum_version_rejected(qMajor: int, qMinor: int, qStep: int, tMajor: int, tMinor: int, tStep: int) -> bool:
    """Pure model of: not versionIsCompatible(MinimumRequiredVersion).
    True == config version INCOMPATIBLE with Tensile __version__ (branch fires -> printExit).
    pre: 0 <= qMajor <= 9 and 0 <= qMinor <= 9 and 0 <= qStep <= 9
    pre: 0 <= tMajor <= 9 and 0 <= tMinor <= 9 and 0 <= tStep <= 9
    post: __return__ == (qMajor != tMajor or qMinor > tMinor or (qMinor == tMinor and qStep > tStep))
    """
    if qMajor != tMajor:
        return True
    if qMinor > tMinor:
        return True
    if qMinor == tMinor:
        if qStep > tStep:
            return True
    return False
